/**
 * One file-type icon, 16px by default (the folder glyph's size in a tree row).
 * Always `.files-icon` — the class app.css colours through `data-kind` — plus
 * the caller's own class for where it sits (an editor chip, a tab).
 */
export function fileIcon(f: FileIcon, size = 16, extra?: string): SVGSVGElement {
  const svg = pathIcon(FILE_ICON_PATHS[f.icon], size);
  svg.classList.add('files-icon');
  if (extra !== undefined) svg.classList.add(extra);
  svg.setAttribute('data-kind', f.kind);
  svg.setAttribute('data-icon', f.icon);
  return svg;
}
